function openUnpaidReport(a,unpaidBookings,unpaidImported,unpaidMonthly,unpaid,unpaidDue){const rows=[];unpaidBookings.forEach(x=>rows.push([x.business||x.name||'',x.email||'',nice(x.date),money(x.price||0),x.hold_until?new Date(x.hold_until).toLocaleDateString('en-US',{timeZone:'America/New_York'}):'']));unpaidImported.forEach(x=>{const ev=a.events.find(e=>e.id===x.event_id);rows.push([x.business||x.name||'',x.email||'',ev?nice(ev.date)+' — '+(ev.location||''):x.event_date?nice(x.event_date):(x.date?nice(x.date):''),money(x.invoice_amount||0),x.invoice_due_date?nice(x.invoice_due_date):''])});unpaidMonthly.forEach(x=>{const picked=(x.items||[]).flatMap(i=>Array.isArray(i.market_dates)?i.market_dates:[]);const dates=picked.length?picked.map(m=>nice(m.date)+' — '+(m.location||m.market_name||'')).join(', '):(x.items||[]).map(i=>i.date?nice(i.date)+(i.location?' — '+i.location:''):'').filter(Boolean).join(', ')||x.billing_period||'';rows.push([x.business||x.vendor_name||'',x.vendor_email||'',dates,money(Math.max(0,Number(x.amount||0)-Number(x.discount||0)+Number(x.late_fee||0))),x.due_date?nice(x.due_date):''])});printTable('Unpaid Invoice Report','All outstanding invoices',['Name','Email','Market date','Amount','Due date'],rows,unpaid+' unpaid invoices · Total due '+money(unpaidDue));}
function printTable(title,subtitle,headers,rows,summary=''){const w=window.open('','_blank');if(!w){notice('Allow pop-ups to print this report.');return;}w.document.write(`<!doctype html><html><head><title>${esc(title)}</title><meta name="viewport" content="width=device-width"><style>@page{size:letter;margin:.5in}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#111;font-size:10pt;margin:0}h1{font-size:19pt;margin:0 0 3px}h2{font-size:12pt;font-weight:normal;margin:0 0 12px}.summary{font-weight:bold;margin:0 0 12px}table{width:100%;border-collapse:collapse;table-layout:auto}th,td{padding:6px 5px;border-bottom:1px solid #bbb;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{font-size:8.5pt;text-transform:uppercase;border-bottom:2px solid #222}tr{break-inside:avoid}footer{margin-top:16px;font-size:8pt;color:#555}</style></head><body><h1>Trinity Crafters Market</h1><h2>${esc(title)}${subtitle?' · '+esc(subtitle):''}</h2>${summary?`<p class="summary">${esc(summary)}</p>`:''}<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v??'')}</td>`).join('')}</tr>`).join('')}</tbody></table><footer>Printed ${new Date().toLocaleString('en-US',{timeZone:'America/New_York'})} Eastern</footer><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();}
function printVendorInvoice(x){const ev=x.event,w=window.open('','_blank');if(!w){notice('Allow pop-ups to print this invoice.');return;}const num=String(x.id||'').slice(0,8).toUpperCase(),status=x.paystatus==='paid'?'PAID':'AMOUNT DUE',market=ev?nice(ev.date)+' — '+(ev.location||marketName(ev)):'';w.document.write(`<!doctype html><html><head><title>Invoice ${esc(num)}</title><meta name="viewport" content="width=device-width"><style>@page{size:letter;margin:.45in}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#173f38;margin:0;background:#f7f7f1}.sheet{max-width:850px;margin:24px auto;background:#fff;border:1px solid #d7dfd7}.head{background:#123f38;color:#fff;padding:30px 34px;display:flex;justify-content:space-between;gap:20px}.head h1{font-size:34px;margin:4px 0 0}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:12px}.status{font-weight:700;border:1px solid rgba(255,255,255,.45);padding:8px 12px;height:max-content}.body{padding:30px 34px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:28px}.right{text-align:right}.line{border-top:1px solid #d7dfd7;border-bottom:1px solid #d7dfd7;padding:18px 0;margin:22px 0}.amount{float:right;font-size:20px;font-weight:700}.grand{text-align:right;font-size:24px;font-weight:700}.note{margin-top:30px;padding-top:18px;border-top:1px solid #d7dfd7;color:#586a64}@media print{body{background:#fff}.sheet{border:0;margin:0}.head{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media(max-width:600px){.head,.meta{display:block}.status{display:inline-block;margin-top:14px}.right{text-align:left;margin-top:18px}}</style></head><body><div class="sheet"><div class="head"><div><div class="eyebrow">Trinity Crafters Market</div><h1>Vendor Invoice</h1></div><div class="status">${esc(status)}</div></div><div class="body"><div class="meta"><div><strong>Bill to</strong><p>${esc(x.business||x.name||'Vendor')}<br>${esc(x.name||'')}<br>${esc(x.email||'')}</p></div><div class="right"><strong>Invoice #</strong><p>${esc(num)}</p><strong>Market date</strong><p>${esc(ev?nice(ev.date):'')}</p>${x.due?'<strong>Due date</strong><p>'+esc(nice(String(x.due).slice(0,10)))+'</p>':''}</div></div><div class="line"><strong>Vendor space — ${esc(market)}</strong><span class="amount">${money(x.amount)}</span><div style="clear:both"></div></div>${x.paystatus==='paid'?'<p><strong>Payment method:</strong> '+esc(x.payment_method||'Recorded payment')+(x.payment_reference?' · '+esc(x.payment_reference):'')+(x.card_last4?' · '+esc((x.card_brand||'Card')+' •••• '+x.card_last4):'')+'</p>':''}<p class="grand">Total ${x.paystatus==='paid'?'paid':'due'}: ${money(x.amount)}</p><div class="note">Thank you for being part of Trinity Crafters Market.<br>trinitycraftersmarket@gmail.com</div></div></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();}
async function parseAttendeePdf(file){
 if(!file||file.type!=='application/pdf')throw Error('Choose a PDF file.');
 if(file.size>12*1024*1024)throw Error('PDF must be 12 MB or smaller.');
 notice('Reading PDF…');
 const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@6.3.289/build/pdf.mjs');
 pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@6.3.289/build/pdf.worker.mjs';
 const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,out=[];
 const norm=x=>String(x||'').toLowerCase().replace(/[^a-z0-9/@.+ -]+/g,' ').replace(/\s+/g,' ').trim();
 const aliases={
  first:['first name','firstname','first'],
  last:['last name','lastname','last'],
  phone:['phone number','telephone','mobile','cell','phone'],
  email:['email address','e-mail','email'],
  category:['vendor category','product category','category'],
  business:['business name','company name','vendor business','business','company'],
  space:['inside/outside','inside outside','indoor/outdoor','indoor outdoor','location','space']
 };
 const classify=t=>{const n=norm(t);for(const [k,list] of Object.entries(aliases))if(list.some(a=>n===a||n.includes(a)))return k;return null;};
 for(let n=1;n<=pdf.numPages;n++){
  const page=await pdf.getPage(n),content=await page.getTextContent();
  const items=content.items.map(z=>({str:String(z.str||'').trim(),x:Number(z.transform?.[4]||0),y:Number(z.transform?.[5]||0),w:Number(z.width||0)})).filter(z=>z.str);
  const rows=[];items.sort((a,b)=>b.y-a.y||a.x-b.x).forEach(it=>{let r=rows.find(q=>Math.abs(q.y-it.y)<4);if(!r){r={y:it.y,items:[]};rows.push(r);}r.items.push(it);});rows.sort((a,b)=>b.y-a.y).forEach(r=>r.items.sort((a,b)=>a.x-b.x));
  let headerMap={},headerBottom=Infinity;
  for(let i=0;i<Math.min(rows.length,20);i++){
   const r=rows[i],joined=norm(r.items.map(x=>x.str).join(' '));
   for(const [key,list] of Object.entries(aliases)){
    if(headerMap[key]!=null)continue;
    let hit=r.items.find(x=>list.some(a=>norm(x.str)===a||norm(x.str).includes(a)));
    if(!hit&&list.some(a=>joined.includes(a))){
      const words=list.flatMap(a=>a.split(' ')).filter(w=>w.length>3),candidates=r.items.filter(x=>words.some(w=>norm(x.str).includes(w)));
      if(candidates.length)hit=candidates[0];
    }
    if(hit){headerMap[key]=hit.x;headerBottom=Math.min(headerBottom,r.y);}
   }
  }
  const keys=Object.entries(headerMap).sort((a,b)=>a[1]-b[1]);
  if(keys.length>=3){
   const centers=keys.map(x=>x[1]),cuts=[-Infinity,...centers.slice(1).map((x,i)=>(centers[i]+x)/2),Infinity];
   for(const r of rows.filter(r=>r.y<headerBottom-2)){
    const obj={name:'',business:'',email:'',phone:'',category:'',space:''};
    keys.forEach(([key],i)=>{const val=r.items.filter(z=>z.x>=cuts[i]&&z.x<cuts[i+1]).map(z=>z.str).join(' ').trim();if(key==='first')obj.name=val;else if(key==='last')obj.name=[obj.name,val].filter(Boolean).join(' ');else if(key==='space')obj.space=val;else obj[key]=val;});
    const rowText=r.items.map(x=>x.str).join(' ');
    if(!obj.email){const m=rowText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);if(m)obj.email=m[0];}
    if(!obj.phone){const m=rowText.match(/(?:\+?1[ .-]?)?\(?\d{3}\)?[ .-]?\d{3}[ .-]?\d{4}/);if(m)obj.phone=m[0];}
    if(/^(inside|indoor)$/i.test(obj.space))obj.space='Inside';else if(/^(outside|outdoor)$/i.test(obj.space))obj.space='Outside';
    if((obj.name||obj.business)&&(obj.email||obj.phone||obj.category||obj.space))out.push(obj);
   }
  }else{
   for(const r of rows){
    const text=r.items.map(x=>x.str).join(' '),email=text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0]||'',phone=text.match(/(?:\+?1[ .-]?)?\(?\d{3}\)?[ .-]?\d{3}[ .-]?\d{4}/)?.[0]||'';
    const space=/\b(inside|indoor)\b/i.test(text)?'Inside':/\b(outside|outdoor)\b/i.test(text)?'Outside':'';
    if(email||phone){const cleaned=text.replace(email,'').replace(phone,'').replace(/\b(inside|indoor|outside|outdoor)\b/ig,'').replace(/\s+/g,' ').trim();out.push({name:cleaned,business:'',email,phone,category:'',space});}
   }
  }
 }
 const unique=[],seen=new Set();
 for(const r of out){const key=(r.email||r.phone||[r.name,r.business].join('|')).toLowerCase().replace(/\s+/g,'');if(!key||seen.has(key))continue;seen.add(key);unique.push(r);}
 if(unique.length)return unique.slice(0,500);
 throw Error('I could not read vendor rows from this PDF. You can still use Add row to enter the attendees manually.');
}
