function syncPublicEventSchema(){
  document.getElementById('event-schema')?.remove();
  const events=(data&&data.events||[]).filter(e=>e&&e.date);
  if(!events.length)return;
  const localDateTime=(d,t)=>{const day=String(d).slice(0,10),time=String(t||'').slice(0,8);return time?day+'T'+time:day};
  const graph=events.map(e=>({
    "@type":"Event",
    "@id":"https://trinitylutzmarkets.com/market-dates#event-"+encodeURIComponent(e.id),
    "name":(marketName(e)||"Trinity Crafters Market")+" — "+nice(e.date),
    "description":"Shop local makers, handcrafted finds and small businesses at this community craft market.",
    "startDate":localDateTime(e.date,e.start_time),
    ...(e.end_time?{"endDate":localDateTime(e.date,e.end_time)}:{}),
    "eventStatus":"https://schema.org/EventScheduled",
    "eventAttendanceMode":"https://schema.org/OfflineEventAttendanceMode",
    "isAccessibleForFree":true,
    "location":{"@type":"Place","name":e.location||marketName(e)||"Trinity Crafters Market",...(e.address?{"address":e.address}:{})},
    "organizer":{"@id":"https://trinitylutzmarkets.com/#organization"},
    "url":"https://trinitylutzmarkets.com/market-dates#market-details?event="+encodeURIComponent(e.id)
  }));
  const s=document.createElement('script');s.type='application/ld+json';s.id='event-schema';s.textContent=JSON.stringify({"@context":"https://schema.org","@graph":graph});document.head.appendChild(s);
}
